import{_ as d}from"./chunks/ArticleMetadata.Xa7L4Afm.js";import{_ as f,D as r,o,c as p,I as s,w as E,k as n,a as h,R as i,b as m,e as A}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const v=JSON.parse('{"title":"消息队列与 MQ 核心知识","description":"异步、解耦、削峰、交付语义与 Kafka 和传统消息队列的差别。","frontmatter":{"title":"消息队列与 MQ 核心知识","date":"2026-11-05T00:00:00.000Z","category":"Java课程","tags":["Java","Kafka","MQ"],"description":"异步、解耦、削峰、交付语义与 Kafka 和传统消息队列的差别。"},"headers":[],"relativePath":"courses/java/16-Kafka/02-消息队列与MQ核心知识.md","filePath":"courses/java/16-Kafka/02-消息队列与MQ核心知识.md","lastUpdated":1793880744000}'),k={name:"courses/java/16-Kafka/02-消息队列与MQ核心知识.md"},u=n("h1",{id:"消息队列与-mq-核心知识",tabindex:"-1"},[h("消息队列与 MQ 核心知识 "),n("a",{class:"header-anchor",href:"#消息队列与-mq-核心知识","aria-label":'Permalink to "消息队列与 MQ 核心知识"'},"​")],-1),B=i('<h2 id="核心术语" tabindex="-1">核心术语 <a class="header-anchor" href="#核心术语" aria-label="Permalink to &quot;核心术语&quot;">​</a></h2><ul><li><strong>消息（message）</strong>：一次业务事实或命令，通常含 key、value、时间戳和 headers。</li><li><strong>Topic</strong>：消息的逻辑名称；Kafka Topic 由多个分区组成。</li><li><strong>分区（partition）</strong>：有序追加日志。顺序只在单个分区内有保证。</li><li><strong>offset</strong>：分区内消息的位置，不是全局唯一序号。</li><li><strong>消费组（consumer group）</strong>：组内实例分工读分区；不同组各读一份。</li></ul><h2 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to &quot;什么时候用&quot;">​</a></h2><p>异步处理能缩短请求等待，解耦让生产方不必直接调用所有下游；队列还能缓冲流量尖峰。但消息会晚到、重复、积压，不能把同步事务的成功直接等同于消息链路成功。</p><p>例如“订单创建”接口原本同步调用库存、通知、报表三个服务，只要其中一个慢，接口就慢。改成订单服务写入 <code>OrderCreated</code> 事件后，三个下游各用自己的消费组读取，就可以独立扩缩容和失败重试。但订单接口返回时，只能说订单写入及发送步骤按设计完成；不能说通知已经送达。</p>',5),C=i('<p>同一个消费组分摊分区，不同消费组各自保留进度。若只有两个分区，同一组开五个实例也不会让五个实例同时处理五个分区；多出的实例会空闲。</p><h2 id="kafka-和传统-mq-的关注点" tabindex="-1">Kafka 和传统 MQ 的关注点 <a class="header-anchor" href="#kafka-和传统-mq-的关注点" aria-label="Permalink to &quot;Kafka 和传统 MQ 的关注点&quot;">​</a></h2><p>JMS 是 Java 消息 API 规范，AMQP 是消息协议；Kafka 提供自己的分区日志与客户端协议。传统队列常强调消息出队及路由，Kafka 强调记录保留、按 offset 重读和独立消费组。两者都能异步解耦，选择时看是否需要重放、多组独立读取、顺序范围、吞吐与运维能力，而不是只比较“能不能发消息”。</p><h2 id="交付语义" tabindex="-1">交付语义 <a class="header-anchor" href="#交付语义" aria-label="Permalink to &quot;交付语义&quot;">​</a></h2><p>“最多一次”可能丢，“至少一次”可能重，“恰好一次”需要限定 Kafka 事务与读写边界，不能自动覆盖外部数据库。实务中常用至少一次消费，并用业务 ID 做幂等。Kafka 与 JMS/AMQP 的接口和路由模型不同，不应把术语机械对应。<a href="https://kafka.apache.org/documentation/#design" target="_blank" rel="noreferrer">Kafka 设计文档</a>可继续查证。</p><p>假设消费服务先更新 MySQL，再提交 offset：数据库成功、提交前进程崩溃，重启就可能再次更新。以 <code>orderId</code> 做唯一约束或幂等记录，才能让重复消息不产生第二次业务效果。反过来先提交 offset 再更新数据库，崩溃会导致这条消息被跳过，业务结果缺失。</p>',6);function P(a,g,M,T,D,K){const l=d,_=r("ClientOnly"),c=r("Mermaid");return o(),p("div",null,[u,s(_,null,{default:E(()=>{var e,t;return[(((e=a.$frontmatter)==null?void 0:e.aside)??!0)&&(((t=a.$frontmatter)==null?void 0:t.showArticleMetadata)??!0)?(o(),m(l,{key:0,article:a.$frontmatter},null,8,["article"])):A("",!0)]}),_:1}),B,s(c,{id:"mermaid_382ee1a4",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E8%AE%A2%E5%8D%95%E6%9C%8D%E5%8A%A1%20Producer%5D%20--%3E%7COrderCreated%2C%20key%3Dorder-7%7C%20T%5BTopic%3A%20order.events%5D%0A%20%20%20%20T%20--%3E%20P0%5B%E5%88%86%E5%8C%BA%200%EF%BC%9A%E8%BF%BD%E5%8A%A0%E6%97%A5%E5%BF%97%E5%92%8C%20offset%5D%0A%20%20%20%20T%20--%3E%20P1%5B%E5%88%86%E5%8C%BA%201%EF%BC%9A%E8%BF%BD%E5%8A%A0%E6%97%A5%E5%BF%97%E5%92%8C%20offset%5D%0A%20%20%20%20P0%20--%3E%20G1%5B%E5%BA%93%E5%AD%98%E6%B6%88%E8%B4%B9%E7%BB%84%5D%0A%20%20%20%20P1%20--%3E%20G1%0A%20%20%20%20P0%20--%3E%20G2%5B%E9%80%9A%E7%9F%A5%E6%B6%88%E8%B4%B9%E7%BB%84%5D%0A%20%20%20%20P1%20--%3E%20G2"}),C])}const S=f(k,[["render",P]]);export{v as __pageData,S as default};
